// --------------------------------------------------------
// QR Photo Album Slideshow — Tap + Auto-Slide + Swipe
// --------------------------------------------------------

let photos = [];
let totalPhotos = 0;
let currentIndex = 0;
let autoInterval = null;
let audioPlaying = false;
let preloadIndex = 0;
let preloadIndex2 = 1;

// DOM Elements (initialized after photos data loads)
let photoEl = null;
let tapOverlay = null;
let musicToggle = null;
let photoCounter = null;
let prevBtn = null;
let nextBtn = null;

// --- Load photo data from photos.json (generated by Node script) ---
function loadPhotosData() {
  return fetch('photos.json')
    .then(res => res.json())
    .then(data => {
      photos = data.photos;
      totalPhotos = data.total;
      return totalPhotos;
    })
    .catch(err => {
      console.error('Error loading photos.json:', err);
      return 0;
    });
}

// --- Show photo at index ---
function showPhoto(index, noPreload = false) {
  if (totalPhotos === 0) return;
  currentIndex = (index + totalPhotos) % totalPhotos;
  if (photoEl) photoEl.src = photos[currentIndex];

  // Update counter
  if (photoCounter) photoCounter.textContent = `${currentIndex + 1} / ${totalPhotos}`;

  // Preload next 2 images (lightweight — just src request)
  if (!noPreload && photoEl) {
    preloadImages();
  }
}

// --- Preload 2 images ahead (memory efficient) ---
function preloadImages() {
  if (totalPhotos === 0) return;
  // Clear any stale indexes
  preloadIndex = (preloadIndex + 1) % totalPhotos;
  preloadIndex2 = (preloadIndex2 + 1) % totalPhotos;

  if (preloadIndex < totalPhotos) {
    const img = new Image();
    img.src = photos[preloadIndex];
    img.onload = () => { /* loaded */ };
  }
  if (preloadIndex2 < totalPhotos && preloadIndex2 !== preloadIndex) {
    const img2 = new Image();
    img2.src = photos[preloadIndex2];
    img2.onload = () => { /* loaded */ };
  }
}

// --- Auto-slide every 5 seconds ---
function startAutoSlide() {
  if (autoInterval) clearInterval(autoInterval);
  if (totalPhotos === 0) return;
  autoInterval = setInterval(() => {
    showPhoto(currentIndex + 1); // advance one
  }, 5000);
}

// --- Tap anywhere to advance + reset timer ---
function initTapHandler() {
  if (totalPhotos === 0) return;
  // Initial tap to start (bypass audio autoplay)
  const tapHandler = e => {
    e.preventDefault();

    // Remove overlay after first tap
    if (tapOverlay) tapOverlay.style.display = 'none';
    document.body.removeEventListener('touchstart', tapHandler, { passive: false });
    document.body.removeEventListener('mousedown', tapHandler);

    // Start music after first user interaction
    startMusic();

    // Start auto-slide
    startAutoSlide();
  };

  document.body.addEventListener('touchstart', tapHandler, { passive: false });
  document.body.addEventListener('mousedown', tapHandler);
}

// --- Swipe gestures (left/right) ---
function initSwipeHandler() {
  if (totalPhotos === 0) return;
  let startX = 0;

  const handleStart = e => {
    startX = e.touches ? e.touches[0].clientX : e.clientX;
  };

  const handleEnd = e => {
    const endX = e.changedTouches ? e.changedTouches[0].clientX : e.clientX;
    const diff = endX - startX;

    if (Math.abs(diff) > 30) {
      if (diff > 0) {
        // swipe right → previous photo
        showPhoto(currentIndex - 1);
      } else {
        // swipe left → next photo
        showPhoto(currentIndex + 1);
      }
      // Reset auto-slide timer after swipe
      clearInterval(autoInterval);
      startAutoSlide();
    }
  };

  document.body.addEventListener('touchstart', handleStart, { passive: false });
  document.body.addEventListener('touchend', handleEnd, { passive: false });
  document.body.addEventListener('mousedown', handleStart);
  document.body.addEventListener('mouseup', handleEnd);
}

// --- Music toggle ---
function startMusic() {
  const audio = document.getElementById('bg-audio');
  if (!audioPlaying) {
    audio.play().catch(() => {/* browsers often block until tap */});
    audioPlaying = true;
    if (musicToggle) musicToggle.textContent = '🔊';
  }
}

function toggleMusic() {
  const audio = document.getElementById('bg-audio');
  if (!totalPhotos) return;
  if (audioPlaying) {
    audio.pause();
    audioPlaying = false;
    if (musicToggle) musicToggle.textContent = '🔇';
  } else {
    audio.currentTime = 0;
    audio.play().catch(() => {});
    audioPlaying = true;
    if (musicToggle) musicToggle.textContent = '🔊';
  }
}

// --- Initialize everything after data loads ---
function initApp() {
  // Set photo element reference
  photoEl = document.getElementById('photo');
  tapOverlay = document.getElementById('tap-overlay');
  musicToggle = document.getElementById('music-toggle');
  photoCounter = document.getElementById('photo-counter');
  prevBtn = document.getElementById('prev');
  nextBtn = document.getElementById('next');

  // Show first photo
  showPhoto(0, true);

  // Init handlers
  initTapHandler();
  initSwipeHandler();

  // Start auto-slide
  startAutoSlide();

  // Start preload loop
  setInterval(preloadImages, 1000); // gentle preload
}

// --- Button listeners ---
if (prevBtn) {
  prevBtn.addEventListener('click', e => {
    e.stopPropagation();
    showPhoto(currentIndex - 1);
    clearInterval(autoInterval);
    startAutoSlide();
  });
}

if (nextBtn) {
  nextBtn.addEventListener('click', e => {
    e.stopPropagation();
    showPhoto(currentIndex + 1);
    clearInterval(autoInterval);
    startAutoSlide();
  });
}

if (musicToggle) {
  musicToggle.addEventListener('click', toggleMusic);
}

// --- Start the app: load data first, then init ---
loadPhotosData().then(initApp);